// Lishaq Solutions — minimal interactions
(function () {
  // Mobile nav
  const toggle = document.querySelector('.menu-toggle');
  const links = document.querySelector('.nav-links');
  if (toggle && links) {
    toggle.addEventListener('click', () => links.classList.toggle('open'));
  }

  // Active link
  const currentPath = window.location.pathname.replace(/\/$/, ''); // Remove trailing slash
  
  document.querySelectorAll('.nav-links a:not(.btn)').forEach((a) => {
    const href = a.getAttribute('href').replace(/\/$/, ''); // Remove trailing slash
    
    // Remove any existing active class
    a.classList.remove('active');
    
    // Homepage
    if (href === '/lishaqsolutions/' && (currentPath === '/lishaqsolutions/' || currentPath === '')) {
      a.classList.add('active');
    }
    // Other pages
    else if (href === currentPath) {
      a.classList.add('active');
    }
    // Child pages (e.g., /services/pos-system should highlight Services)
    else if (currentPath.startsWith(href + '/') && href !== '/lishaqsolutions/') {
      a.classList.add('active');
    }
  });

  // Scroll reveal
  const io = new IntersectionObserver((entries) => {
    entries.forEach((e) => {
      if (e.isIntersecting) {
        e.target.classList.add('in');
        io.unobserve(e.target);
      }
    });
  }, { threshold: 0.12 });
  document.querySelectorAll('.reveal').forEach((el) => io.observe(el));

})();